Review this function for averaging marks, any edge cases I should handle?

def weighted_average(scores, weights):
    total = sum(s * w for s, w in zip(scores, weights))
    return total / sum(weights)

print(weighted_average([78, 85, 92], [0.2, 0.3, 0.5]))
